name: partial-refund-rounding-down
description: "Finance rule: partial refunds are always rounded DOWN to the whole cent, never to nearest"
metadata:
  node_type: memory
  type: project
  originSessionId: 931719b0-0534-428f-817b-8ba4d887c682
  modified: 2026-11-26T09:27:07.407Z
