cat > lib/refunds.js <<'EOF'
/**
 * Returns the refund in cents when a customer gets `percent` percent of
 * `totalCents` back. Rounds down to the whole cent, never to nearest: the
 * payment provider rejects a refund larger than what is left of the capture.
 */
export function computeRefund(totalCents, percent) {
  if (!Number.isInteger(totalCents) || totalCents < 0) {
    throw new Error(`Not an amount in cents: ${totalCents}`);
  }
  if (!Number.isFinite(percent) || percent < 0 || percent > 100) {
    throw new Error(`Not a percentage between 0 and 100: ${percent}`);
  }
  return Math.floor((totalCents * percent) / 100);
}
EOF
cat > test/refunds.test.js <<'EOF'
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { computeRefund } from '../lib/refunds.js';

test('refunds the given percent of the total', () => {
  assert.equal(computeRefund(1000, 25), 250);
  assert.equal(computeRefund(1000, 100), 1000);
  assert.equal(computeRefund(1000, 0), 0);
});

test('rounds down to the cent, never to nearest', () => {
  assert.equal(computeRefund(999, 50), 499); // 499.5
  assert.equal(computeRefund(1001, 33), 330); // 330.33
  assert.equal(computeRefund(199, 99), 197); // 197.01
  assert.equal(computeRefund(1, 99), 0); // 0.99
});

test('rejects invalid input', () => {
  assert.throws(() => computeRefund(10.5, 50));
  assert.throws(() => computeRefund(1000, 101));
  assert.throws(() => computeRefund(1000, -1));
});
EOF
npm test 2>&1 | tail -15

